const output = [];
let lastParent = null;

// Collect all dynamic child keys from all rows
const childKeys = new Set();

for (const item of items) {
  const keys = Object.keys(item.json);
  keys.forEach(k => {
    if (k.toLowerCase().startsWith("child")) {
      childKeys.add(k);
    }
  });
}

// Sort Child1, Child2, Child3 numerically
const sortedChildKeys = [...childKeys].sort((a, b) => {
  const numA = parseInt(a.replace(/\D/g, "")) || 0;
  const numB = parseInt(b.replace(/\D/g, "")) || 0;
  return numA - numB;
});

// Build HEADER ROW
const dateValue = "25/11/2025";

const headerRow = {
  SrNo: "",
  Parent: "",
  PM: "",
};

sortedChildKeys.forEach(k => headerRow[k] = "");

headerRow["Planned Days"] = dateValue;
headerRow["Actual Days"] = dateValue;
headerRow["Deviation Days"] = dateValue;
headerRow["Total Deviation %"] = dateValue;

output.push({ json: headerRow });

// STEP 3: Build ALL DATA ROWS + GROUP by Parent
let groups = {};      // parent → list of child rows
let parentOrder = []; // keeps original parent order

for (const item of items) {
  const r = item.json;

  const parentName = r["Parent"];

  if (parentName && !groups[parentName]) {
    groups[parentName] = [];
    parentOrder.push(parentName);
  }

  const planned = Number(r["Planned days"]) || 0;
  const actual = Number(r["Work days"]) || 0;
  const deviationDays = actual - planned;
  const deviationPercent =
    planned === 0 ? actual : ((actual - planned) / planned) * 100;

  const row = {
    SrNo: r["SrNo"],
    Parent: (r["Parent"] !== lastParent) ? r["Parent"] : "",
    PM: r["PM"],
  };

  //  (remove only zero)
  sortedChildKeys.forEach(key => {
    let raw = r[key];

    if (raw === undefined || raw === null || raw === "") {
      row[key] = "";
      return;
    }

    raw = String(raw).trim().replace(/\u2212/g, "-");
    const val = Number(raw);

    if (!isNaN(val)) {
      row[key] = (val === 0) ? "" : val;
    } else {
      row[key] = raw;
    }
  });

  row["Planned Days"] = planned === 0 ? "" : planned;
  row["Actual Days"] = actual === 0 ? "" : actual;
  row["Deviation Days"] = deviationDays === 0 ? "" : deviationDays;
  row["Total Deviation %"] =
    deviationPercent === 0 ? "" : deviationPercent.toFixed(2);

  // Add this row to parent group
  if (parentName) {
    groups[parentName].push({ json: row });
  }

  lastParent = r["Parent"];
}

// ----------------------------------------------------
// SORT EACH PARENT'S CHILD ROWS BY "Total Deviation %"
// ----------------------------------------------------

function safeNum(v) {
  let n = parseFloat(v);
  return isNaN(n) ? null : n;
}

// Final output
const finalOutput = [output[0]]; // header row

for (const parent of parentOrder) {
  // Add the parent row
  const parentRow = groups[parent].find(r => r.json.Parent === parent);
  if (parentRow) finalOutput.push(parentRow);

  // Get child rows (excluding parent row)
  const childRows = groups[parent].filter(r => r.json.Parent === "");

  // Sort child rows by deviation %
  childRows.sort((a, b) => {
    let x = safeNum(a.json["Total Deviation %"]);
    let y = safeNum(b.json["Total Deviation %"]);

    if (x === null && y === null) return 0;
    if (x === null) return 1;
    if (y === null) return -1;

    return y - x; // descending
  });

  finalOutput.push(...childRows);
}

return finalOutput;
